head.b:skin:
/* Variable definitions
<Group description="Colors" selector="body">
<Variable name="keycolor" description="Accent color" type="color" default="#0e7a3d" value="#0e7a3d"/>
</Group>
*/

/* Mono - technical theme with automatic dark mode.
   Zero JS, zero external requests, mobile-first. */

:root{
  --accent:$(keycolor);
  --bg:#fafafa;
  --text:#1c1917;
  --muted:#78716c;
  --border:#e7e5e4;
  --soft:#f5f5f4;
  color-scheme:light;
  --mono:ui-monospace,SFMono-Regular,Menlo,Consolas,"Liberation Mono",monospace;
}
@media (prefers-color-scheme:dark){
  :root{
    --accent:#4ade80;
    --bg:#0c0a09;
    --text:#e7e5e4;
    --muted:#a8a29e;
    --border:#292524;
    --soft:#1c1917;
    color-scheme:dark;
  }
}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{
  margin:0;
  background:var(--bg);
  color:var(--text);
  font:1rem/1.65 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
}
.wrap{max-width:46rem;margin-inline:auto;padding-inline:1rem}
a{color:var(--accent);text-decoration:none}
a:hover{text-decoration:underline}
img{max-width:100%;height:auto}

.site-header{border-bottom:1px solid var(--border);padding-block:1.25rem}
.header-inner{display:flex;flex-wrap:wrap;align-items:center;gap:.5rem 1.25rem}
.site-title{font-size:1.25rem;font-weight:700;line-height:1.2;margin:0;font-family:var(--mono)}
.site-title a{color:inherit}
.site-title a::before{content:"~/ ";color:var(--accent)}
.pages-section ul{display:flex;flex-wrap:wrap;gap:0 1rem;list-style:none;margin:0;padding:0}
.pages-section a{color:var(--muted);font-size:.875rem;font-family:var(--mono)}
.search-form{margin-inline-start:auto}
.search-form input{
  max-width:9.5rem;padding:.35rem .6rem;font-family:var(--mono);font-size:.85rem;
  border:1px solid var(--border);border-radius:.375rem;background:var(--soft);color:var(--text);
}

.site-main{padding-block:1.5rem 2.5rem}
.results-note{color:var(--muted);font-size:.9rem;font-family:var(--mono)}

.post-summary{padding-block:1.5rem;border-bottom:1px dashed var(--border)}
.post-summary:last-of-type{border-bottom:0}
.post-title{font-size:1.375rem;line-height:1.3;margin:.25rem 0}
.post-title a{color:inherit}
.post-meta{color:var(--muted);font-size:.8125rem;font-family:var(--mono);margin:.25rem 0 .75rem}
.post-labels a{display:inline-block;margin-inline-start:.5rem}
.post-labels a::before{content:"#"}
.post-thumb{display:block;margin-bottom:.75rem}
.post-thumb img{display:block;width:100%;border:1px solid var(--border);border-radius:.375rem}
.post-snippet{color:var(--muted);font-size:.9375rem}
.read-more{font-family:var(--mono);font-size:.9rem}
.read-more::after{content:" ->"}

.post-full .post-title{font-size:2rem;line-height:1.2}
.post-body{overflow-wrap:break-word}
.post-body code{font-family:var(--mono);font-size:.9em;background:var(--soft);padding:.1em .3em;border-radius:.25rem}
.post-body pre{overflow-x:auto;padding:1rem;background:var(--soft);border:1px solid var(--border);border-radius:.5rem}
.post-body pre code{background:none;padding:0}
.post-body blockquote{
  margin-inline:0;padding-inline-start:1rem;
  border-inline-start:3px solid var(--accent);color:var(--muted);
}
.post-body table{border-collapse:collapse;display:block;overflow-x:auto}
.post-body th,.post-body td{border:1px solid var(--border);padding:.4rem .7rem}
.post-body img{border:1px solid var(--border);border-radius:.375rem}

.pager{display:flex;justify-content:space-between;gap:1rem;padding-block:1.5rem;font-family:var(--mono);font-size:.9rem}

.comments{margin-top:2.5rem;padding-top:1rem;border-top:1px solid var(--border)}
.comment-form input[type="text"],.comment-form textarea{max-width:100%}
#comment-editor{width:100% !important;max-width:100%}

.site-footer{
  border-top:1px solid var(--border);color:var(--muted);
  font-size:.8125rem;font-family:var(--mono);padding-block:1.5rem;text-align:center;
}

@media (min-width:48rem){
  .post-full .post-title{font-size:2.25rem}
}
